function getFileName(url: string): string {
    const fileName = url.split('/').pop()?.split('?')[0].split('#')[0] ?? '';

    if (!fileName) {
        Log.warn('[FileUtils] Could not get attachment name', {url});
    }

    return decodeURIComponent(fileName).replace(CONST.REGEX.ILLEGAL_FILENAME_CHARACTERS, '_');
}

function cleanFileName(fileName: string): string {
    return fileName.replace(/[^a-zA-Z0-9\-._]/g, '_');
}

function appendTimeToFileName(fileName: string): string {
    const file = splitExtensionFromFileName(fileName);
    let newFileName = `${file.fileName}-${DateUtils.getDBTime()}`;
    // Replace illegal characters before trying to download the attachment.
    newFileName = newFileName.replace(CONST.REGEX.ILLEGAL_FILENAME_CHARACTERS, '_');
    if (file.fileExtension) {
        newFileName += `.${file.fileExtension}`;
    }
    return newFileName;
}

function isLocalFile(receiptUri?: string | number): boolean {
    if (!receiptUri) {
        return false;
    }
    return typeof receiptUri === 'number' || receiptUri?.startsWith('blob:') || receiptUri?.startsWith('file:') || receiptUri?.startsWith('/');
}

function handleDownload(url: string, fileName?: string, successMessage?: string): Promise<void> {
    return new Promise((resolve) => {
        const dirs = RNFetchBlob.fs.dirs;

        // Android files will download to Download directory
        const path = dirs.DownloadDir;
        // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Disabling this line for safeness as nullish coalescing works only if the value is undefined or null, and since fileName can be an empty string we want to default to `FileUtils.getFileName(url)`
        const attachmentName = FileUtils.appendTimeToFileName(fileName || FileUtils.getFileName(url));

        const isLocalFile = url.startsWith('file://');

        let attachmentPath = isLocalFile ? url : undefined;
        let fetchedAttachment: Promise<void | FetchBlobResponse> = Promise.resolve();

        if (!isLocalFile) {
            // Fetching the attachment
            fetchedAttachment = RNFetchBlob.config({
                fileCache: true,
                path: `${path}/${attachmentName}`,
                addAndroidDownloads: {
                    useDownloadManager: true,
                    notification: false,
                    path: `${path}/Expensify/${attachmentName}`,
                },
            }).fetch('GET', url);
        }

        // Resolving the fetched attachment
        fetchedAttachment
            .then((attachment) => {
                if (!isLocalFile && (!attachment || !attachment.info())) {
                    return Promise.reject();
                }

                if (!isLocalFile) {
                    attachmentPath = (attachment as FetchBlobResponse).path();
                }

                return RNFetchBlob.MediaCollection.copyToMediaStore(
                    {
                        name: attachmentName,
                        parentFolder: 'Expensify',
                        mimeType: null,
                    },
                    'Download',
                    attachmentPath ?? '',
                );
            })
            .then(() => {
                if (attachmentPath) {
                    RNFetchBlob.fs.unlink(attachmentPath);
                }
                FileUtils.showSuccessAlert(successMessage);
            })
            .catch(() => {
                FileUtils.showGeneralErrorAlert();
            })
            .finally(() => resolve());
    });
}

function downloadFile(fileUrl: string, fileName: string) {
    const dirs = RNFetchBlob.fs.dirs;

    // The iOS files will download to documents directory
    const path = dirs.DocumentDir;

    // Fetching the attachment
    return RNFetchBlob.config({
        fileCache: true,
        path: `${path}/${fileName}`,
        addAndroidDownloads: {
            useDownloadManager: true,
            notification: true,
            path: `${path}/Expensify/${fileName}`,
        },
    }).fetch('GET', fileUrl);
}

async function getChecklistCategoriesForPullRequest(): Promise<Set<string>> {
    const checks = new Set<string>();
    if (prNumber !== undefined) {
        const changedFiles = await GithubUtils.paginate(GithubUtils.octokit.pulls.listFiles, {
            owner: CONST.GITHUB_OWNER,
            repo: CONST.APP_REPO,
            pull_number: prNumber,
            per_page: 100,
        });
        const possibleCategories = await Promise.all(
            Object.values(CHECKLIST_CATEGORIES).map(async (category) => ({
                items: category.items,
                doesCategoryApply: await category.detect(changedFiles),
            })),
        );
        for (const category of possibleCategories) {
            if (category.doesCategoryApply) {
                for (const item of category.items) {
                    checks.add(item);
                }
            }
        }
    }
    return checks;
}

async function getNumberOfItemsFromAuthorChecklist(): Promise<number> {
    const response = await fetch(pathToAuthorChecklist);
    const fileContents = await response.text();
    const checklist = partitionWithChecklist(fileContents)[1];
    const numberOfChecklistItems = (checklist.match(/\[ \]/g) ?? []).length;
    return numberOfChecklistItems;
}

async function detectReactComponentInFile(filename: string): Promise<boolean | undefined> {
    const params = {
        owner: CONST.GITHUB_OWNER,
        repo: CONST.APP_REPO,
        path: filename,
        ref: (github.context.payload as GithubPaylod)?.pull_request?.head.ref,
    };
    try {
        const {data} = await GithubUtils.octokit.repos.getContent(params);
        const content = nodeBase64ToUtf8('content' in data ? data?.content ?? '' : '');
        return detectReactComponent(content, filename);
    } catch (error) {
        console.error('An unknown error occurred with the GitHub API: ', error, params);
    }
}

async function detect(changedFiles: Array<{filename: string; status: string}>): Promise<boolean> {
    const filteredFiles = changedFiles.filter(({filename, status}) => status === 'added' && (filename.endsWith('.js') || filename.endsWith('.ts') || filename.endsWith('.tsx')));
    try {
        await promiseSome(
            filteredFiles.map(({filename}) => detectReactComponentInFile(filename)),
            (result) => !!result,
        );
        return true;
    } catch (err) {
        return false;
    }
}

function getNumberOfItemsFromReviewerChecklist() {
    console.log('Getting the number of items in the reviewer checklist...');
    return new Promise<number>((resolve, reject) => {
        https
            .get(pathToReviewerChecklist, (res) => {
                let fileContents = '';
                res.on('data', (chunk) => {
                    fileContents += chunk;
                });
                res.on('end', () => {
                    const numberOfChecklistItems = (fileContents.match(/- \[ \]/g) ?? []).length;
                    console.log(`There are ${numberOfChecklistItems} items in the reviewer checklist.`);
                    resolve(numberOfChecklistItems);
                });
            })
            .on('error', (err) => {
                console.error(err);
                reject(err);
            });
    });
}

function createHubsWithArticles(hubs: string[], platformName: ValueOf<typeof platformNames>, routeHubs: Hub[]) {
    hubs.forEach((hub) => {
        // Iterate through each directory in articles
        fs.readdirSync(`${docsDir}/articles/${platformName}/${hub}`).forEach((fileOrFolder) => {
            // If the directory content is a markdown file, then it is an article
            if (fileOrFolder.endsWith('.md')) {
                const articleObj = getArticleObj(fileOrFolder);
                pushOrCreateEntry(routeHubs, hub, 'articles', articleObj);
                return;
            }

            // For readability, we will use the term section to refer to subfolders
            const section = fileOrFolder;
            const articles: Article[] = [];

            // Each subfolder will be a section containing articles
            fs.readdirSync(`${docsDir}/articles/${platformName}/${hub}/${section}`).forEach((subArticle) => {
                const order = getOrderFromArticleFrontMatter(`${docsDir}/articles/${platformName}/${hub}/${section}/${subArticle}`);
                articles.push(getArticleObj(subArticle, order));
            });

            pushOrCreateEntry(routeHubs, hub, 'sections', {
                href: section,
                title: toTitleCase(section.replaceAll('-', ' ')),
                articles,
            });
        });
    });
}

function createBasicPR(num: number) {
    const branchName = `pr-${num}`;
    const content = `Changes from PR #${num}`;
    const filePath = path.resolve(process.cwd(), `PR${num}.txt`);

    Log.info(`Creating PR #${num}`);
    checkoutRepo();
    setupGitAsHuman();
    exec('git pull');
    exec(`git switch -c ${branchName}`);
    fs.appendFileSync(filePath, content);
    exec(`git add ${filePath}`);
    exec(`git commit -m "${content}"`);
    Log.success(`Created PR #${num} in branch ${branchName}`);
}

async function mergeSourceMaps() {
    // Read all .map files in the dist directory
    const sourceMapFiles = fs
        .readdirSync(distDir)
        .filter((file) => file.endsWith('.map'))
        .map((file) => path.join(distDir, file));

    const mergedGenerator = new SourceMapGenerator();

    for (const file of sourceMapFiles) {
        const sourceMapContent = JSON.parse(fs.readFileSync(file, 'utf8')) as RawSourceMap;
        const consumer = await new SourceMapConsumer(sourceMapContent);

        consumer.eachMapping((mapping) => {
            if (!mapping.source) {
                return;
            }

            mergedGenerator.addMapping({
                generated: {
                    line: mapping.generatedLine,
                    column: mapping.generatedColumn,
                },
                original: {
                    line: mapping.originalLine,
                    column: mapping.originalColumn,
                },
                source: mapping.source,
                name: mapping.name,
            });
        });

        // Add the sources content
        consumer.sources.forEach((sourceFile: string) => {
            const content = consumer.sourceContentFor(sourceFile);
            if (content) {
                mergedGenerator.setSourceContent(sourceFile, content);
            }
        });

        consumer.destroy();
    }

    // Write the merged source map to a file
    fs.writeFileSync(outputFile, mergedGenerator.toString());

    console.log(`Merged source map written to ${outputFile}`);
}

function findCpuProfileFiles() {
    const files = fs.readdirSync(process.cwd());
    return files.filter((file) => file.endsWith('.cpuprofile'));
}

function downloadFile(url: string) {
    Logger.log(`Downloading file from URL: ${url}`);
    if (!fs.existsSync(sourcemapDir)) {
        Logger.info(`Creating download directory ${sourcemapDir}`);
        fs.mkdirSync(sourcemapDir);
    }

    const destination = path.join(sourcemapDir, `${argsMap.platform}-sourcemap-${appVersion}.zip`);
    const file = fs.createWriteStream(destination);
    return new Promise<string>((resolve, reject) => {
        https
            .get(url, (response) => {
                response.pipe(file);
                file.on('finish', () => {
                    file.close();
                    Logger.success(`Downloaded file to ${destination}`);
                    resolve(destination);
                });
            })
            .on('error', (error) => {
                fs.unlink(destination, () => {
                    reject(error);
                });
            });
    });
}

function unpackZipFile(zipPath: string) {
    Logger.info(`Unpacking file ${zipPath}`);
    const command = `unzip -o ${zipPath} -d ${sourcemapDir}`;
    execSync(command, {stdio: 'inherit'});
    Logger.info(`Deleting zip file ${zipPath}`);
    return new Promise<void>((resolve, reject) => {
        fs.unlink(zipPath, (error) => (error ? reject(error) : resolve()));
    });
}
